<?php require __DIR__.'/../config/bootstrap.php';if(!empty($_SESSION['admin_id'])){header('Location:dashboard.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf($_POST['csrf']??'');$st=$pdo->prepare("SELECT * FROM admins WHERE email=? LIMIT 1");$st->execute([trim($_POST['email']??'')]);$a=$st->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_email']=$a['email'];header('Location:dashboard.php');exit;}$error='Invalid email or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="admin.css"></head><body class="login"><form class="loginbox" method="post"><div class="mark">R+</div><h1>Admin portal</h1><p>Manage campaigns, settings and leads.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Sign in</button></form></body></html>
